import React from 'react';

import type { Decoration, Node as RicosNode } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewDecorator } from './../../ricos-types/index.js';

import { SKETCH_DATA_HOOK } from './data-hooks.js';
import {
  DEFAULT_ANIMATE,
  DEFAULT_COLOR,
  DEFAULT_STYLE,
  STYLE_TO_ARIA_LABEL,
  TEXT_LAYER_Z_INDEX,
} from './defaults.js';

// Heavy renderer (DOM walking, group merging, overlay SVGs, roughjs) is
// loaded only when the first sketch span actually mounts. If the
// rendered document has no sketch decorations, `rule()` always
// returns false ⇒ `decorate` never runs ⇒ this chunk is never fetched.
let scheduleRender: ((target: HTMLElement) => void) | null = null;
let pendingTargets: HTMLElement[] | null = null;

const lazyScheduleRender = (target: HTMLElement) => {
  if (scheduleRender) {
    scheduleRender(target);
    return;
  }
  if (pendingTargets) {
    pendingTargets.push(target);
    return;
  }
  pendingTargets = [target];
  void import(
    /* webpackChunkName: "ricos_plugin_sketch_viewer_lazy" */ './schedule-sketch-render.js'
  ).then(mod => {
    scheduleRender = mod.scheduleSketchRender;
    const queued = pendingTargets ?? [];
    pendingTargets = null;
    for (const queuedTarget of queued) {
      scheduleRender(queuedTarget);
    }
  });
};

export const SketchDecorator: NodeViewDecorator<JSX.Element> = {
  rule: (node: RicosNode) =>
    !!node.textData?.decorations?.some(({ type }) => type === Decoration_Type.SKETCH),
  decorate: ({ element, node, context }) => {
    const decoration = node.textData?.decorations?.find(
      (d: Decoration) => d.type === Decoration_Type.SKETCH
    );
    const data = decoration?.sketchData;
    const style = data?.variant ?? DEFAULT_STYLE;
    const color = data?.color ?? DEFAULT_COLOR;
    const animate = !context.isPrint && (data?.animate ?? DEFAULT_ANIMATE);
    const ariaLabel = STYLE_TO_ARIA_LABEL[style] ?? STYLE_TO_ARIA_LABEL[DEFAULT_STYLE];
    const jsxElement = element as JSX.Element;

    const refCallback = (target: HTMLSpanElement | null) => {
      if (!target) {
        return;
      }
      (target.ownerDocument.defaultView ?? window).ricosSketchesReady = false;
      lazyScheduleRender(target);
    };

    return (
      <span
        key={`rough-${jsxElement?.key ?? ''}`}
        ref={refCallback}
        data-hook={SKETCH_DATA_HOOK}
        data-style={style}
        data-color={color}
        data-animate={String(animate)}
        aria-label={ariaLabel}
        // Text layer reference for `getOverlayZIndex`: HIGHLIGHT sits
        // below this z-index, every other style above.
        style={{ position: 'relative', zIndex: TEXT_LAYER_Z_INDEX, textDecoration: 'inherit' }}
      >
        {jsxElement}
      </span>
    );
  },
};
